 require(argc==2,"real r9 ledger path");auto ledger=eventio::read_json(argv[1]);const std::size_t n=4307694;std::vector<std::int32_t>owner(n,-1);std::vector<std::string>keys;keys.reserve(ledger.at("groups").size());std::size_t nonuniform=0;for(const auto&g:ledger.at("groups")){const int gi=int(keys.size());keys.push_back(g.at("id"));nonuniform+=g.at("per_row_weight").is_null();for(const auto&i:g.at("actual_row_indices")){const auto raw=i.get<std::size_t>();require(raw<n&&owner[raw]<0,"real parent ledger duplicated raw source");owner[raw]=gi;}}
